exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · base64url                                              ★★☆ core
//  concepts: Base64Url · padding
// ─────────────────────────────────────────────────────────────────────────
//
//  Tokens in URLs and JWTs cannot carry "+", "/" or "=". Base64Url swaps
//  two characters and drops the padding — and the reader must restore it.

using static Bootcamp.Check;

string ToUrlSafe(string b64)
{
    return b64.Replace('+', '-').Replace('/', '_').TrimEnd('=');
}

string FromUrlSafe(string s)
{
    var b64 = s.Replace('-', '+').Replace('_', '/');
    return b64 + new string('=', (4 - b64.Length % 4) % 4);
}

