    Eq(FromUrlSafe("ab-_"), "ab+/"));

Test("FromUrlSafe(\"abc\") -> \"abc=\" (one pad)", () =>
    Eq(FromUrlSafe("abc"), "abc="));

Test("FromUrlSafe(\"ab\") -> \"ab==\" (two pads)", () =>
    Eq(FromUrlSafe("ab"), "ab=="));

Test("ToUrlSafe(\"\") -> \"\" (boundary)", () =>
    Eq(ToUrlSafe(""), ""));

Test("\"aGk=\" round-trips through \"aGk\"", () =>
{
    Eq(ToUrlSafe("aGk="), "aGk");
