exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  06 · luhn                                                   ★★★ stretch
//  concepts: checksum · right-to-left digits
// ─────────────────────────────────────────────────────────────────────────
//
//  Every card number ends in a check digit. Validate it before calling the
//  payment provider and typos never cost an API round-trip.

using static Bootcamp.Check;

bool IsLuhnValid(string digits)
{
    int sum = 0;
    bool doubleIt = false;
    for (int i = digits.Length - 1; i >= 0; i--)
    {
        char c = digits[i];
        if (c < '0' || c > '9') return false;
        int d = c - '0';
        if (doubleIt)
        {
            d *= 2;
            if (d > 9) d -= 9;
        }
        sum += d;
        doubleIt = !doubleIt;
    }
    return sum % 10 == 0;
}

