exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  07 · stable bucket                                          ★★★ stretch
//  concepts: persistable hashing · unsigned overflow
// ─────────────────────────────────────────────────────────────────────────
//
//  Shard tenants across N buckets — and get the SAME bucket tomorrow, on
//  another server. string.GetHashCode() is randomized per process: never.

using static Bootcamp.Check;

int Bucket(string key, int buckets)
{
    uint h = 0;
    foreach (char ch in key)
        h = unchecked(h * 31 + ch);
    return (int)(h % (uint)buckets);
}

