    Eq(Bucket("api", 7), 5));

Test("Bucket(\"user-42\", 7) -> 6 (h wraps past 2^32)", () =>
    Eq(Bucket("user-42", 7), 6));

Test("Bucket(\"\", 5) -> 0 (boundary)", () =>
    Eq(Bucket("", 5), 0));

Test("Bucket(\"tenant-9\", 4) -> 2", () =>
    Eq(Bucket("tenant-9", 4), 2));

Test("the same key always lands in the same bucket", () =>
    Eq(Bucket("tenant-9", 4), Bucket("tenant-9", 4)));

